const config = $getWorkflowStaticData('global');

config.SLA_HOURS = 16;
config.emailRecipients = [
  "direactor@company.com",
  "csm@company.com"
];
config.VIP_DOMAINS = [
  "imp-customer.com",
  "escalated-cucstomer.com"
];
config.excludedSenderEmails = [
  "internal@company.com"
];
config.excludedSenderDomains = [
  "google.com"
];
config.escalationEmails = [
  "ceo@company.com",
  "cto@company.com"
];
config.emailSubject = "Daily Email Risk Digest";

return config;

const threadMap = new Map();

for (const item of $input.all()) {
  const threadId = item.json.threadId;
  const receivedMs = new Date(item.json.receivedAt).getTime();

  if (!threadMap.has(threadId)) {
    threadMap.set(threadId, {
      item,
      latestTs: receivedMs,
      count: 1
    });
  } else {
    const entry = threadMap.get(threadId);
    entry.count += 1;

    if (receivedMs > entry.latestTs) {
      entry.item = item;
      entry.latestTs = receivedMs;
    }
  }
}

const result = [];

for (const [, entry] of threadMap.entries()) {
  result.push({
    json: {
      ...entry.item.json,
      isThread: entry.count > 1,
      threadMessageCount: entry.count
    }
  });
}

return result;

const config = $getWorkflowStaticData('global');

const today = new Date().toLocaleDateString("en-US", {
  month: "short",
  day: "2-digit",
  year: "numeric",
});

const items = $input.all();

// ---- COUNT SUMMARY ----
let high = 0, medium = 0, low = 0;

for (const item of items) {
  const s = Number(item.json.score);
  if (s >= 3) high++;
  else if (s >= 1.5) medium++;
  else low++;
}

const total = high + medium + low;

// ---- HEADER ----
let headerLine = "Daily Email Risk Digest";
if (total > 0) {
  const parts = [];
  if (high) parts.push(`${high} High`);
  if (medium) parts.push(`${medium} Medium`);
  if (low) parts.push(`${low} Low`);
  headerLine = `${total} Email${total > 1 ? "s" : ""} Need Attention | ${parts.join(", ")}`;
}

// ---- COLOR MAP (PRESENTATION ONLY) ----
function chipColor(color) {
  switch (color) {
    case "red": return "background:#e74c3c;color:#fff;";
    case "amber": return "background:#f1c40f;color:#000;";
    case "blue": return "background:#3498db;color:#fff;";
    case "purple": return "background:#8e44ad;color:#fff;";
    case "grey": return "background:#ecf0f1;color:#333;";
    default: return "background:#ecf0f1;color:#333;";
  }
}

// ---- RISK LABEL (PRESENTATION) ----
function getRiskLabel(score) {
  if (score >= 3) return { label: "HIGH RISK", color: "red" };
  if (score >= 1.5) return { label: "MEDIUM RISK", color: "amber" };
  return { label: "LOW RISK", color: "grey" };
}

// ---- HTML START ----
let html = `
<div style="font-family: Arial, sans-serif; background:#f6f8fa; padding:20px;">
  <div style="max-width:700px; margin:auto; background:#ffffff; padding:20px; border-radius:8px;">
    <h2 style="margin:0; color:#222;">${headerLine}</h2>
    <p style="margin-top:4px; color:#666; font-size:14px;">Date: ${today}</p>
    <hr style="border:none; border-top:1px solid #eaeaea;"/>
`;

let counter = 0;

// ---- EMAIL CARDS ----
for (const item of items) {
  const mail = item.json;
  counter++;

  const gmailLink = `https://mail.google.com/mail/u/0/#inbox/${mail.id}`;
  const risk = getRiskLabel(Number(mail.score));

  html += `
    <div style="border:1px solid #eaeaea; border-radius:6px; padding:14px; margin-top:16px;">

      <!-- Subject -->
      <div style="font-size:15px; font-weight:bold; color:#222;">
        #${counter} • 
        <a href="${gmailLink}" target="_blank"
           style="color:#222; text-decoration:none;"
           onmouseover="this.style.textDecoration='underline'"
           onmouseout="this.style.textDecoration='none'">
          ${mail.subject}
        </a>
      </div>

      <!-- Risk Label + Score -->
      <div style="margin-top:6px;">
        <span style="
          display:inline-block;
          ${chipColor(risk.color)}
          padding:4px 8px;
          font-size:12px;
          border-radius:4px;
          margin-right:6px;
          white-space:nowrap;
        ">
          ${risk.label}
        </span>

        <span style="
          display:inline-block;
          background:#f4f6f8;
          color:#333;
          padding:4px 8px;
          font-size:12px;
          border-radius:4px;
          white-space:nowrap;
        ">
          Risk Score: ${Number(mail.score).toFixed(2)}
        </span>
      </div>

      <!-- From -->
      <div style="margin-top:6px; color:#666; font-size:13px;">
        From: ${mail.from.address}
      </div>

      <!-- Per-email summary -->
      ${
        mail.summary
          ? `
          <div style="margin-top:8px; font-size:13px; color:#555;">
            <strong>Summary:</strong> ${mail.summary}
          </div>
          `
          : ""
      }

      <!-- Chips -->
      <div style="margin-top:10px;">
  `;

  for (const chip of mail.chips || []) {
    html += `
      <span style="
        display:inline-block;
        ${chipColor(chip.color)}
        padding:4px 8px;
        font-size:12px;
        border-radius:4px;
        margin-right:6px;
        margin-bottom:6px;
        white-space:nowrap;
      ">
        ${chip.label}
      </span>
    `;
  }

  html += `
      </div>
    </div>
  `;
}

// ---- FOOTER ----
html += `
    <hr style="border:none; border-top:1px solid #eaeaea; margin-top:20px;"/>
    <p style="font-size:12px; color:#999;">
      Tip: Click the subject to open the email in Gmail.
    </p>
  </div>
</div>
`;

return [{
  json: {
    subject: config.emailSubject,
    recipients: config.emailRecipients,
    html
  }
}];

const config = $getWorkflowStaticData('global');

// ---- CONFIG ----
const SLA_HOURS = Number(config.SLA_HOURS ?? 24);
const VIP_DOMAINS = config.VIP_DOMAINS ?? [];
const ESCALATION_EMAILS = config.escalationEmails ?? [];

// ---- PRECOMPUTED SET ----
const escalationSet = new Set(
  ESCALATION_EMAILS.map(e => e.toLowerCase())
);

// ---- HELPERS ----
function getResponseRisk(pendingHours) {
  return Math.min(1, pendingHours / SLA_HOURS);
}

function getUrgencyFactor(pendingHours) {
  return 1 + Math.log2(1 + pendingHours / 4);
}

function isVipSender(email) {
  const domain = email?.split("@")[1]?.toLowerCase();
  return VIP_DOMAINS.includes(domain);
}

function isEscalated(recipients) {
  if (!Array.isArray(recipients)) return false;
  return recipients.some(r => escalationSet.has(r.toLowerCase()));
}

function formatPendingLabel(hours) {
  if (hours < 48) return `${Math.round(hours)}h Since Pending Reply`;
  return `${Math.round(hours / 24)}d Since Pending Reply`;
}

// ---- MAIN ----
const now = Date.now();

for (const item of $input.all()) {
  const receivedAt = new Date(item.json.receivedAt).getTime();
  const pendingHours = (now - receivedAt) / (1000 * 60 * 60);

  const responseRisk = getResponseRisk(pendingHours);
  const urgencyFactor = getUrgencyFactor(pendingHours);

  const vip = isVipSender(item.json.from?.address);
  const escalated = isEscalated(item.json.recipients);
  const sentimentRisk = Number(item.json.isNegativeSentiment ?? 0);

  const escalationRisk = escalated ? 1 : 0;

  const baseRisk =
    0.55 * responseRisk +
    0.30 * escalationRisk +
    0.15 * sentimentRisk;

  let importanceMultiplier = 1.0;
  if (vip) importanceMultiplier = 1.2;
  if (escalated) importanceMultiplier = Math.max(importanceMultiplier, 1.5);

  const finalScore =
    baseRisk * urgencyFactor * importanceMultiplier;

  // ---- CHIPS (WITH COLORS) ----
  const chips = [];

  // Pending Reply
  chips.push({
    label: formatPendingLabel(pendingHours),
    color: pendingHours >= SLA_HOURS ? "red" : "amber"
  });

  // SLA Breach
  // if (pendingHours >= SLA_HOURS) {
  //   chips.push({ label: "SLA Breached", color: "red" });
  // }

  // VIP
  if (vip) {
    chips.push({ label: "VIP Account", color: "purple" });
  }

  // Escalation
  if (escalated) {
    chips.push({ label: "Escalated", color: "blue" });
  }

  // Negative sentiment
  if (sentimentRisk > 0) {
    chips.push({ label: "Negative Sentiment", color: "red" });
  }

  // ---- ATTACH ----
  item.json.pendingHours = Math.round(pendingHours);
  item.json.response_risk = Number(responseRisk.toFixed(5));
  item.json.urgency_factor = Number(urgencyFactor.toFixed(5));
  item.json.base_risk = Number(baseRisk.toFixed(5));
  item.json.importance_multiplier = importanceMultiplier;
  item.json.score = Number(finalScore.toFixed(5));

  item.json.isVipSender = vip;
  item.json.isEscalated = escalated;
  item.json.chips = chips;
}

// ---- SORT DESC ----
return $input.all().sort((a, b) => b.json.score - a.json.score);

// 1. Extract the raw text from the AI node
let rawText = $input.item.json.output[0].content[0].text;

// 2. Clean the text (Remove markdown backticks if they exist)
const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

try {
  const parsed = JSON.parse(cleanText);

  // 3. Return the data, mapping snake_case to camelCase for consistency
  return {
    summary: parsed.summary || "No summary provided",
    threadClosed: parsed.thread_closed ?? false,
    is_negative_sentiment: parsed.is_negative_sentiment ?? false
  };
} catch (error) {
  // If it still fails, this will tell you exactly why in the output
  return {
    summary: "Parsing Error: " + error.message,
    threadClosed: false,
    is_negative_sentiment: false,
    debug_raw_text: cleanText // This helps you see what actually came in
  };
}

function safeAddressList(field) {
  if (!field?.value) return [];
  if (Array.isArray(field.value)) {
    return field.value.map(v => v.address?.toLowerCase()).filter(Boolean);
  }
  if (field.value.address) {
    return [field.value.address.toLowerCase()];
  }
  return [];
}

function getSender(mail) {
  return (
    mail.json.replyTo?.value?.[0]?.address ||
    mail.json.from?.value?.[0]?.address ||
    null
  );
}

/**
 * Extract latest meaningful email body from n8n Gmail `json.text`
 * Safe for LLM usage.
 */
function extractLatestBodyFromText(text, maxChars = 1500) {
  if (!text) return "";

  let cleaned = text;

  const quotePatterns = [
    /^from: .*$/im,
    /^on .* wrote:$/im,
    /^sent: .*$/im,
    /^to: .*$/im,
    /^subject: .*$/im,
    /^-----original message-----/im,
    /^-----forwarded message-----/im
  ];

  for (const pattern of quotePatterns) {
    const idx = cleaned.search(pattern);
    if (idx !== -1) {
      cleaned = cleaned.substring(0, idx);
    }
  }

  cleaned = cleaned
    .split("\n")
    .filter(line => !line.trim().startsWith(">"))
    .join("\n");

  const signatureMarkers = [
    "\n--\n",
    "\n—\n",
    "\nRegards,",
    "\nThanks,",
    "\nBest,"
  ];

  for (const marker of signatureMarkers) {
    const idx = cleaned.indexOf(marker);
    if (idx !== -1) {
      cleaned = cleaned.substring(0, idx);
      break;
    }
  }

  cleaned = cleaned
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();

  return cleaned.length > maxChars ? cleaned.slice(0, maxChars) : cleaned;
}

function getAllRecipients(mail) {
  const recipients = [
    ...safeAddressList(mail.to),
    ...safeAddressList(mail.cc),
    ...safeAddressList(mail.bcc)
  ];

  return [...new Set(recipients)];
}

return $input.all().map(mail => ({
  json: {
    id: mail.json.id,
    threadId: mail.json.threadId,
    subject: mail.json.subject || "",
    from: getSender(mail),
    to: safeAddressList(mail.json.to),
    cc: safeAddressList(mail.json.cc),
    bcc: safeAddressList(mail.json.bcc),
    recipients: getAllRecipients(mail.json),
    receivedAt: mail.json.date,
    labelIds: mail.json.labelIds || [],
    body: extractLatestBodyFromText(mail.json.text)
  }
}));
